    "description": "秦皇岛市气象台2026年11月8日00时22分发布暴雪红色预警信号。 目前秦皇岛大部分地区已经出现暴雪天气，其中青龙、卢龙、抚宁、昌黎、海港区北部、山海关区，6小时降雪量将达到15毫米以上。 预计到今天下午两点前，秦皇岛全市中南部地区仍有3～10毫米降雪，北部地区仍有2～5毫米降雪。 截至发稿前，降雪仍在持续，积雪、结冰风险高，提醒大家尽量减少外出，注意出行安全。",
    "content": "秦皇岛市气象台2026年11月8日00时22分发布暴雪红色预警信号。 目前秦皇岛大部分地区已经出现暴雪天气，其中青龙、卢龙、抚宁、昌黎、海港区北部、山海关区，6小时降雪量将达到15毫米以上。 预计到今天下午两点前，秦皇岛全市中南部地区仍有3～10毫米降雪，北部地区仍有2～5毫米降雪。 截至发稿前，降雪仍在持续，积雪、结冰风险高，提醒大家尽量减少外出，注意出行安全。"
