    "description": "英国国王查尔斯三世的一名助手称，查尔斯三世将考虑对中国进行国事访问。如果成行，这将是英国君主时隔40年再次访华。 据法新社报道，这名王室高级助手向记者说：“如果政府问‘国王会不会访问中国’，我想我们会非常慎重地考虑。” 英国君主迄今仅对中国进行过一次国事访问。查尔斯三世的母亲、已故女王伊丽莎白二世，曾在1986年10月与丈夫菲利普亲王一同访华。据当时的报道，他们到访了北京、上海和广州。 这次访问是在中英两国签署《中英联合声明》两年后进行…",
