    "content": "快科技11月8日消息，据报道， 11月4日国家市场监督管理总局缺陷产品召回中心集中发布多起车辆召回公告，涉及大众、丰田、路特斯、Jeep等品牌，合计召回超80万辆。 召回原因涵盖软件控制、转向、燃油、零部件松动等多项安全隐患，然而召回信息发布后，不法分子迅速炮制虚假诈骗短信，精准围猎车主。 11月5日至7日，至少10家车企密集发布声明辟谣。 这些不法分子的诈骗套路也高度相似，通过发短信冒充车企官方，声称车辆涉及“高田气囊召回”或“安全气囊紧急召回”，在短信中，他们不仅能准确报出车主姓名、车型、车牌号甚至车架号，部分…"
