    "author": "",
    "description": "听录音、找素材、生画面……AI正深度介入媒体工作的方方面面。 AI越来越能干，还不用休息，媒体人会早点下班？还是难保饭碗？ 第七届世界媒体峰会上，新华社记者与来自世界各地的媒体人一道，探访“智能变革中的媒体使命与合作行动”。 面对AI带来的变革，来自世界各地的媒体人分享了他们的观察与思考： AI让新闻生产更高效。阿根廷《侧影报》数字总监阿古斯蒂诺·丰泰韦基亚感慨，“那些重复性的、不需要深度思考的报道内容被自动化了”。媒体从业者得以有更多…",
    "content": "听录音、找素材、生画面……AI正深度介入媒体工作的方方面面。 AI越来越能干，还不用休息，媒体人会早点下班？还是难保饭碗？ 第七届世界媒体峰会上，新华社记者与来自世界各地的媒体人一道，探访“智能变革中的媒体使命与合作行动”。 面对AI带来的变革，来自世界各地的媒体人分享了他们的观察与思考： AI让新闻生产更高效。阿根廷《侧影报》数字总监阿古斯蒂诺·丰泰韦基亚感慨，“那些重复性的、不需要深度思考的报道内容被自动化了”。媒体从业者得以有更多精力投入更复杂、深度的报道。 但机器并不等于创造力。瑞士与列支敦士登外国记者协会…"
