    "description": "中国天气网讯 今天(11月8日)，随着寒潮继续南下，北方的降水将迅速缩减，同时南方雨带也将减弱、南压。明后天，全国大部地区将受干冷气团控制，晴或多云天气上线。与此同时，今天至10日，受较强冷空气东移南下影响，我国中东部大部地区气温将普遍下降，南北方多地气温或创下半年来新低。",
