    "content": "上海有着海派文化、红色文化、江南文化丰厚的土壤，市场消费力强、对外交流频繁，剧场硬件也是全国一流，但戏剧创作端的短板与市场热度并不匹配，问题在哪里？著名话剧编剧喻荣军为澎湃新闻撰文详解。 上海拥有全国规模领先的演出市场，演出场次、票房体量长期居全国前列，国有院团都拥有多部经典剧目家底，加上艺术节、剧场集群和院校资源加持，人们有理由对上海的演艺发展有着更大的期待。但是，在繁荣的市场表象之下，戏剧创作领域依然存在着不少结构性的矛盾。 三年行动计划提出六大专项行动，尤其“戏剧创作强源行动”直击行业的“剧本短板”，这既是给…"
