    "description": "2026年11月08日 《中华人民共和国税收征收管理法（修订草案）》通过十四届全国人大常委会第二十五次会议初次审议。此次修订将纳税人合法权益保护贯穿制度设计全链条，聚焦涉税信息保护、申报纠错、税款滞纳金、复议权利保障等社会关切的重点领域，推出一系列制度升级举措，推动税收治理更加注重保护纳税人合法权益。 一道屏障，严格涉税信息保密 “实践中，涉税信息的使用范围、保密边界一直是纳税人的核心关切，信息不当使用、违规泄露风险是经营主体的普遍隐忧…",
    "content": "2026年11月08日 《中华人民共和国税收征收管理法（修订草案）》通过十四届全国人大常委会第二十五次会议初次审议。此次修订将纳税人合法权益保护贯穿制度设计全链条，聚焦涉税信息保护、申报纠错、税款滞纳金、复议权利保障等社会关切的重点领域，推出一系列制度升级举措，推动税收治理更加注重保护纳税人合法权益。 一道屏障，严格涉税信息保密 “实践中，涉税信息的使用范围、保密边界一直是纳税人的核心关切，信息不当使用、违规泄露风险是经营主体的普遍隐忧。”国家税务总局有关司局负责人表示，在税收征管数字化深入推进的背景下，涉税信息采…"
