    "content": "2026年11月08日 立冬时节，在位于内蒙古鄂尔多斯市准格尔旗的国家能源集团准能集团黑岱沟露天煤矿，生产现场热火朝天，一辆辆巨型无人驾驶矿卡精准穿梭、有序作业。 集控中心大屏上，实时回传的现场画面里，车辆参数、行驶路线等信息一目了然。“我们已完成79台300吨级矿卡、116台工程协同设备智能化改造，可24小时连续作业。数字矿山一体化建设，让生产更安全高效。”矿长钮景付说。 2023年6月，习近平总书记在内蒙古考察时强调：“推动传统能源产业转型升级，大力发展绿色能源，做大做强国家重要能源基地，是内蒙古发展的重中之重…"
