    "description": "2026年11月08日 由国务院新闻办公室指导的“2026世界市长对话·宁波”活动近日在浙江宁波举办。活动以“开放融通·共生机遇”为主题，吸引来自15个国家20个城市的市长、市长代表，以及国际组织、企业代表等260余人参加。与会嘉宾围绕开放合作、经贸往来、文明互鉴等议题深入交流与互动，进一步探索中外城市的常态化对话、机制化交流和长效化合作。 经贸往来，港口城市互通互融 东海之滨，宁波舟山港一派繁忙。这座东方大港由20个港区组成，集装箱航…",
