    "content": "2026年11月08日 “十五五”规划纲要提出，“构建以先进制造业为骨干的现代化产业体系”“加快建设贸易强国”。作为支持对外经贸投资发展与国际经济合作的政策性金融机构，中国进出口银行（以下简称“进出口银行”）始终以金融纽带链接中国制造与国际市场，为外贸高质量发展夯实产业根基。 充分发挥政策性金融支持先进制造业的优势 当前，新一轮科技革命和产业变革加速突破，以人工智能为代表的前沿技术持续迭代。先进制造业是发展新质生产力的重要阵地。作为政策性金融机构，进出口银行充分发挥自身服务先进制造业的优势和作用，引导更多金融资源投…"
