    "description": "2026年11月08日 苗绣、银器、竹编、瓷刻、揩漆……进博会现场，一方具有中国风和民族韵味的角落吸引不少观众驻足，这是今年“进博精品荟”首次设立的“非遗工坊”。 当古韵悠然的非物质文化遗产邂逅现代时尚的进博会，会碰撞出怎样令人惊艳的火花？ 一台木制绣架展开半卷绿色布匹，灵动的鸳鸯、摆尾的鱼跃然布面。今年20岁的龙涵彪飞针走线。作为十八洞苗绣传承人，他从小对苗绣耳濡目染：“苗绣色彩鲜艳、纹样丰富且寓意吉祥，是承载苗族历史的重要载体。” …",
    "content": "2026年11月08日 苗绣、银器、竹编、瓷刻、揩漆……进博会现场，一方具有中国风和民族韵味的角落吸引不少观众驻足，这是今年“进博精品荟”首次设立的“非遗工坊”。 当古韵悠然的非物质文化遗产邂逅现代时尚的进博会，会碰撞出怎样令人惊艳的火花？ 一台木制绣架展开半卷绿色布匹，灵动的鸳鸯、摆尾的鱼跃然布面。今年20岁的龙涵彪飞针走线。作为十八洞苗绣传承人，他从小对苗绣耳濡目染：“苗绣色彩鲜艳、纹样丰富且寓意吉祥，是承载苗族历史的重要载体。” 这次在进博会展出的，不仅有传统的苗绣服饰，更有融入苗绣元素又加以日常化改造的创新…"
