    "pub_date": "2026-11-08 08:26:02",
    "author": "",
    "description": "2026年11月08日 在山西博物院的“民族熔炉”展厅中，有一件高13厘米、通长24厘米的青铜染炉。它1983年出土于山西朔州市一座西汉晚期的墓葬，炉身透雕着青龙、白虎、朱雀、玄武四神，故名“四神染炉”。这件精美的烹饪用具，是2000多年前人们席前温酱、分餐而食的生动见证。 四神染炉由承盘、炉体、耳杯三部分组成。承盘略呈椭圆形，侈口，浅腹，平底，是整套器物的底座，承接炉体的余灰。炉体安置于承盘之上，其底座呈长方形，上部透雕四神，体现着汉…",
    "content": "2026年11月08日 在山西博物院的“民族熔炉”展厅中，有一件高13厘米、通长24厘米的青铜染炉。它1983年出土于山西朔州市一座西汉晚期的墓葬，炉身透雕着青龙、白虎、朱雀、玄武四神，故名“四神染炉”。这件精美的烹饪用具，是2000多年前人们席前温酱、分餐而食的生动见证。 四神染炉由承盘、炉体、耳杯三部分组成。承盘略呈椭圆形，侈口，浅腹，平底，是整套器物的底座，承接炉体的余灰。炉体安置于承盘之上，其底座呈长方形，上部透雕四神，体现着汉代“四方有灵”的空间观念。炉身一侧置一叶状鋬，便于端持。下部四足呈侏儒俯身背手状…"
