    "content": "2026年11月08日 近日，澳大利亚国家美术馆向我国返还两件流失文物，使社会公众关注的目光再次聚焦到了河南巩义北宋皇陵的保护及相关工作。 北宋皇陵坐落于今河南省巩义市，始建于宋太祖乾德元年（963年），止于宋钦宗靖康二年（1127年）北宋灭亡。北宋九帝中，徽宗、钦宗被金人掳掠、囚死漠北，其余七帝皆葬于此；再加上追封宣祖的赵匡胤之父赵弘殷永安陵，合称“七帝八陵”。八陵依次为：宣祖永安陵、太祖永昌陵、太宗永熙陵、真宗永定陵、仁宗永昭陵、英宗永厚陵、神宗永裕陵、哲宗永泰陵。除永安陵为帝后合葬外，其余皇帝和皇后皆实行“同…"
