    "title": "普通案件或将告别“指居”",
    "link": "https://www.infzm.com/contents/344348",
    "pub_date": "2026-11-08 08:00:00",
    "author": "",
    "description": "“无固定居所”这一适用“指居”的情形被删除，只保留后两种情形。这意味着，普通案件中滥用“指居”将成为历史。 南方周末记者 韩谦 责任编辑：钱昊平 2023年9月以来，《南方周末》多次发布与“指居”相关的新闻报道和评论性文章。 “这是此次修法最大的进步。”刑诉法修正草案公开征求意见后，北京大学法学院教授陈永生发现，草案对指定居所监视居住（以下简称“指居”）的适用范围作了重大调整。 按现行刑诉法，监视居住是减少羁押的替代措施，一般在住处执行…",
