    "content": "全球贸易流向和货物结构正在发生变化，国际物流企业也在调整运力配置和投资方向。 在第九届中国国际进口博览会期间，澎湃新闻记者采访UPS、联邦快递及国泰货运等多家国际物流巨头以及航司货运高管发现，AI硬件、半导体设备、先进制造及医疗健康产品等高附加值货物，正在成为航空货运市场的重要增长动力。 与此同时，面对贸易政策变化和供应链不确定性，越来越多物流企业不再只关注运输速度，而是更加重视跨境物流的稳定性、可视化以及合规能力。同时，需求变化也推动物流企业进一步加大投入。 高附加值货物流动增长，航空货运竞争不再只比速度 “今年…"
