    "description": "新华社华盛顿11月7日电（记者黄强 徐剑梅）美军中央司令部7日发布消息称，美军当天在阿曼湾对一艘“试图违反美国对伊朗海上封锁”的货船发动打击，使其丧失航行能力。 消息称，这艘货船多次无视警告，并试图违反美国对伊朗的海上封锁。在船员被撤离后，美军飞机向这艘货船的船尾发射了精确制导炸弹，使其丧失航行能力。 消息称，该船曾试图在停靠伊朗港口后驶离该地区水域。 美军中央司令部还说，自7月以来，美军已强制147艘商船改变航向，并使5艘商船丧失航行…",
    "content": "新华社华盛顿11月7日电（记者黄强 徐剑梅）美军中央司令部7日发布消息称，美军当天在阿曼湾对一艘“试图违反美国对伊朗海上封锁”的货船发动打击，使其丧失航行能力。 消息称，这艘货船多次无视警告，并试图违反美国对伊朗的海上封锁。在船员被撤离后，美军飞机向这艘货船的船尾发射了精确制导炸弹，使其丧失航行能力。 消息称，该船曾试图在停靠伊朗港口后驶离该地区水域。 美军中央司令部还说，自7月以来，美军已强制147艘商船改变航向，并使5艘商船丧失航行能力。此外，还摧毁了10艘伊朗油轮。"
