    "content": "IT之家 11 月 8 日消息，据央视新闻报道，11 月 7 日，中国企业改革与发展研究会发布了《全球能源转型报告（2026）》，数据显示，我国已构建起全球最大、发展最快的可再生能源体系。 报告指出，目前，化石能源活动仍是全球碳排放的最大来源。2025 年，全球与能源相关的二氧化碳排放总量同比增长 0.4%，达 384 亿吨，是 2021 年以来最低增幅。其中， 中国碳排放量下降 0.5% ，美国碳排放量增长 2.4%，成为全球碳排放增长的最大来源。 中国企业改革与发展研究会会长彭华岗介绍，今年上半年， 中国煤电发…"
