    "description": "新华社波哥大11月7日电（记者李子健）哥伦比亚军方7日通过社交媒体发表声明说，该国北部玻利瓦尔省圣罗莎市一处军事基地当天遭无人机袭击，造成3名军人死亡、8名军人重伤，另有多人受到不同程度伤害。 声明说，袭击者使用经过改装、携带爆炸装置的无人机对军事基地发动袭击。事发后，军方立即启动安全应急预案，核查袭击造成的人员伤亡和设施损毁情况。受伤人员已被送医救治。 哥伦比亚总统德拉埃斯普列亚当天通过社交媒体发表声明，强烈谴责此次袭击，向遇难军人家…",
    "content": "新华社波哥大11月7日电（记者李子健）哥伦比亚军方7日通过社交媒体发表声明说，该国北部玻利瓦尔省圣罗莎市一处军事基地当天遭无人机袭击，造成3名军人死亡、8名军人重伤，另有多人受到不同程度伤害。 声明说，袭击者使用经过改装、携带爆炸装置的无人机对军事基地发动袭击。事发后，军方立即启动安全应急预案，核查袭击造成的人员伤亡和设施损毁情况。受伤人员已被送医救治。 哥伦比亚总统德拉埃斯普列亚当天通过社交媒体发表声明，强烈谴责此次袭击，向遇难军人家属表示慰问，并要求有关部门为伤者提供必要的医疗救治和支持。 德拉埃斯普列亚表示，…"
