    "description": "新华社华沙11月7日电（记者岳媛媛）据多家波兰媒体7日报道，波兰克拉科夫中央广场当天发生的枪击事件，已造成6人死亡、15人受伤，伤者包括3名警员。 报道说，枪手驾车过程中随机向路人开枪，后与警方发生交火，枪手受伤后被送往医院。报道援引国防部消息人士的话说，枪手可能是一名退伍军人。 小波兰省警方发言人卡塔日娜·西斯洛当天对媒体表示，被捕枪手是波兰人，具体身份有待查明。根据目前调查情况判断，作案者只有一人。警方在迪特拉街与斯特拉多姆街交叉路…",
    "content": "新华社华沙11月7日电（记者岳媛媛）据多家波兰媒体7日报道，波兰克拉科夫中央广场当天发生的枪击事件，已造成6人死亡、15人受伤，伤者包括3名警员。 报道说，枪手驾车过程中随机向路人开枪，后与警方发生交火，枪手受伤后被送往医院。报道援引国防部消息人士的话说，枪手可能是一名退伍军人。 小波兰省警方发言人卡塔日娜·西斯洛当天对媒体表示，被捕枪手是波兰人，具体身份有待查明。根据目前调查情况判断，作案者只有一人。警方在迪特拉街与斯特拉多姆街交叉路口将其拘捕，被捕时枪手身着军用服装，使用军用型长枪。警方还在其汽车内查获大量枪支…"
