    "content": "新华社华盛顿11月7日电（记者杨伶）美国总统特朗普7日在社交媒体上发文说，他已邀请美国终极格斗冠军赛总裁达纳·怀特担任白宫新闻秘书一职。 特朗普说，达纳·怀特将会是一名“与众不同”的新闻秘书。他还说，已请求达纳·怀特带来一些助手，并列举了数名终极格斗冠军赛选手，“尽管其中一些人并非来自我们国家……我们需要这些人来抵御疯狂的左翼势力”。 美媒报道说，目前尚不清楚达纳·怀特是否接受了特朗普的邀请。 特朗普10月9日宣布任命保守派评论员凯蒂·扎卡里亚出任白宫新闻秘书，接替离职的卡罗琳·莱维特。据美国媒体10月16日报道，…"
