    "title": "智利中部严重交通事故致12死15伤",
    "link": "http://www.news.cn/20261108/e7a6f85fc08142a19a346ccf26f9f88e/c.html",
    "pub_date": "2026-11-08 01:58:59",
    "author": "",
    "description": "新华社圣地亚哥11月7日电（记者朱雨博）智利瓦尔帕莱索大区总统代表米永内斯7日说，该大区圣多明各市当天发生一起严重交通事故，造成至少12人死亡、15人受伤。 根据当地警方信息，当天9时许，圣多明各市一段高速公路上，一辆公共汽车与一辆卡车发生正面碰撞，并波及了一辆轿车。事故伤者已被送往医院，伤势轻重不一。 事故现场照片显示，公共汽车车头严重变形损毁。 圣多明各市长费尔南多·罗德里格斯当天接受当地媒体采访时说，涉事公共汽车上载有妇女和儿童。…",
    "content": "新华社圣地亚哥11月7日电（记者朱雨博）智利瓦尔帕莱索大区总统代表米永内斯7日说，该大区圣多明各市当天发生一起严重交通事故，造成至少12人死亡、15人受伤。 根据当地警方信息，当天9时许，圣多明各市一段高速公路上，一辆公共汽车与一辆卡车发生正面碰撞，并波及了一辆轿车。事故伤者已被送往医院，伤势轻重不一。 事故现场照片显示，公共汽车车头严重变形损毁。 圣多明各市长费尔南多·罗德里格斯当天接受当地媒体采访时说，涉事公共汽车上载有妇女和儿童。 圣多明各市消防部门负责人塞萨尔·卡雷尼奥说，已有大约50名消防员赶往事故现场进…"
