    "content": "新华社莫斯科11月7日电（记者刘恺）俄罗斯外交部发言人扎哈罗娃7日重申，援助乌克兰的“志愿联盟”旗下多国部队将要举行的演习会加剧局势升级，俄方绝不接受在乌部署外国军队。 英国和法国国防部3日发表联合声明，宣布援助乌克兰“志愿联盟”旗下多国部队将于9日至22日举行首次演习，来自11个国家的约2800名军人参加，为乌克兰与俄罗斯达成和平协议后在乌部署部队做准备。 扎哈罗娃7日在回答媒体有关此次演习的提问时说，西方仍然不愿正视俄罗斯合理的安全关切，反而继续加剧局势升级。英法企图利用在乌克兰部署多国部队来保持与俄罗斯对抗的…"
