    "content": "不知道是不是错觉 但感觉 codex 太慢了，而且经常模型加载不出来，然后废话连篇，不说人话 用 claude code 接入了一下，发觉改善不少（但使用 opus 是最好的），不知道是不是错觉，还是真的就这样"
