    "content": "新华社科威特城11月7日电（记者尹炣）萨那消息：也门胡塞武装控制的马西拉电视台7日援引当地医疗部门负责人的消息报道称，也门首都萨那附近一座村庄当天遭沙特阿拉伯空袭造成的死亡人数已升至22人，另有30人受伤。 报道说，医院已接收22具遇难者遗体。报道呼吁医院增派救护车转运伤者，呼吁民众献血帮助救治。 报道称，沙特战机随后还袭击了村内的救援人员，并持续在事发地区上空活动，阻碍救援队伍接近遇袭人员。此外还有两名摄像记者在袭击中受伤。 当天早些时候，马西拉电视台报道说，萨那以东的贝尼·胡谢什地区舍尔耶村当天遭到沙特空袭，5…"
