    "content": "新华社维也纳11月7日电 11月6日，中国常驻维也纳代表团在维也纳联合国总部举办新中国恢复联合国合法席位55周年主题活动。联合国维也纳办事处总干事兼联合国毒品和犯罪问题办公室执行主任朱马、国际原子能机构总干事格罗西、联合国工业发展组织总干事穆勒、《全面禁止核试验条约》组织筹委会临时技秘处执行秘书弗洛伊德、联合国国际贸易法委员会秘书长乔宾-布莱特、联合国外空司司长霍拉-迈尼等国际组织负责人全体出席。各国常驻代表和外交官、智库学者等近200人与会。 中国常驻联合国维也纳办事处和其他国际组织代表李松主持活动。他表示，新中…"
