    "content": "第七届世界媒体峰会11月7日在北京开幕。来自全球112个国家和地区的近330家主流媒体、智库、政府部门以及联合国和其他国际组织等机构的近500名代表出席。 世界媒体峰会是全球媒体界的盛会，本届峰会恰逢新华社建社95周年。来自全球各地的媒体机构代表送出了对新华社的生日祝福。 综合新华社记者报道 新华社音视频部制作"
